# Schluessel und Werte werden ueber die POSITION zusammengefuehrt (zip unten).
# Genau deshalb ist eine Laengenabweichung KEIN Schoenheitsfehler, sondern eine
# stille Verschiebung: wird ein Schluessel in der MITTE von KEYS ergaenzt, ohne
# die Werte an derselben Stelle zu ergaenzen, bekommt jeder Text dahinter den
# falschen Namen -- und `zip` schneidet den Rest wortlos ab. Live vorgekommen am
# 25.08.2026, als zwei Erweiterungen gleichzeitig an dieser Datei arbeiteten.
#
# Deshalb hier ein Abbruch VOR dem Schreiben und keine Warnung danach.
for _code, _werte in sorted(T.items()):
    if len(_werte) != len(KEYS):
        raise SystemExit(
            f"{_code}: {len(_werte)} Texte, aber {len(KEYS)} Schluessel. "
            f"Ab '{KEYS[min(len(_werte), len(KEYS) - 1)]}' stimmt die Zuordnung "
            "nicht mehr — Werte an DERSELBEN Stelle ergaenzen wie den Schluessel."
        )

for k in KEYS:
    zeilen.append(f"  /** {kommentare[k]} */\n  {k}: string;\n")
zeilen.append("};\n\n")

zeilen.append("/** Anzeigename einer Sprache in ihrer EIGENEN Sprache. Ein Wähler, der\n")
zeilen.append(" *  „Dänisch“ auf Deutsch anbietet, hilft dem dänischen Gast nicht. */\n")
zeilen.append("export const SPRACH_NAMEN: Record<string, string> = {\n")
for code in sorted(NAMEN):
    zeilen.append(f'  {code}: "{NAMEN[code]}",\n')
zeilen.append("};\n\n")

zeilen.append("/** Flaggen-Emoji einer Sprache, für den Sprachwähler.\n")
zeilen.append(" *\n")
zeilen.append(" *  Als Emoji und nicht als Icon-Name: der Wähler ist ab sieben Sprachen ein\n")
zeilen.append(" *  natives <select>, und ein <option> rendert ausschließlich Text.\n")
zeilen.append(" *  Die Flagge steht VOR dem Endonym, nie an seiner Stelle — eine Flagge ist\n")
zeilen.append(" *  ein Land, keine Sprache (Deutsch: DE/AT/CH). */\n")
zeilen.append("export const SPRACH_FLAGGEN: Record<string, string> = {\n")
for code in sorted(FLAGGEN):
    zeilen.append(f'  {code}: "{FLAGGEN[code]}",\n')
zeilen.append("};\n\n")

zeilen.append("/** Flagge einer Sprache als Iconify-Name (twemoji).\n")
zeilen.append(" *\n")
zeilen.append(" *  Vorzuziehen, wo HTML erlaubt ist: Regional-Indicator-Emoji haben unter\n")
zeilen.append(" *  Windows keine Glyphe, Chrome und Edge zeigen dort nur die zwei Buchstaben\n")
zeilen.append(" *  des Ländercodes. `SPRACH_FLAGGEN` bleibt für native <option>-Listen. */\n")
zeilen.append("export const SPRACH_FLAGGEN_ICON: Record<string, string> = {\n")
for code in sorted(FLAGGEN_ICON):
    zeilen.append(f'  {code}: "{FLAGGEN_ICON[code]}",\n')
zeilen.append("};\n\n")

zeilen.append("const KATALOG: Record<string, RendererTexte> = {\n")
for code in sorted(T):
    zeilen.append(f"  {code}: {{\n")
    for k, w in zip(KEYS, T[code]):
        zeilen.append(f'    {k}: "{w}",\n')
    zeilen.append("  },\n")
zeilen.append("};\n\n")

zeilen.append('''/** Texte für eine Sprache.
 *
 *  Eine unbekannte Sprache fällt auf Englisch zurück und nicht auf Deutsch: der
 *  Fall tritt nur ein, wenn eine Sprache hinzukommt, für die dieser Katalog noch
 *  keinen Eintrag hat — und Englisch versteht in dieser Lage mehr als Deutsch.
 *  Die Sprachwahl selbst prüft ohnehin gegen die Liste (lib/sprache.ts), hier
 *  ist es nur der letzte Halt. */
export function texte(sprache: string): RendererTexte {
  return KATALOG[sprache] ?? KATALOG.en!;
}
''')

import pathlib
pathlib.Path("builder/lib/texte.ts").write_text("".join(zeilen), encoding="utf-8")
print(f"builder/lib/texte.ts: {len(T)} Sprachen x {len(KEYS)} Schlüssel")
